import{z as n,x as p,o as i,c as E,q as t,j as s,D as e,d as l,s as r,S as c}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Linux capabilities","description":"","frontmatter":{"title":"Linux capabilities","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linux-capabilities.md","filePath":"cs/linux-capabilities.md","lastUpdated":1791063341000}'),d={name:"cs/linux-capabilities.md"};function A(u,a,B,_,b,m){const o=p("Mermaid");return i(),E("div",null,[a[2]||(a[2]=t('<h1 id="linux-capabilities" tabindex="-1">Linux capabilities <a class="header-anchor" href="#linux-capabilities" aria-label="Permalink to &quot;Linux capabilities&quot;">​</a></h1><div class="epigraph"><p>capabilities 把 root 切成可单独授予的位：绑定低端口、加载模块、改时钟各占一位，进程不必再拿完整 uid 0。</p><footer>—— 据 POSIX 1003.1e 草案直觉；Linux capabilities(7)；[内核加固](/cs/kernel-hardening) 为利用缓解对照</footer></div><p><a href="/cs/timer-wheel">上一课</a>收口调度。<a href="/cs/kernel-user">用户/内核</a> 用 uid。缺口是 <strong>把超级用户拆成位图</strong>：bounding set、ambient、file capabilities。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统：uid 0 全能。cap：<code>CAP_NET_BIND_SERVICE</code> 即可 <code>:80</code>。缺口：effective/permitted/inheritable 三集合；execve 如何算新集；<code>CAP_SYS_ADMIN</code> 仍过大。本课不把每一位 man 页抄完。</p><p><span class="marginnote">术语翻译：三集合分工——permitted 是「最多能有哪些」的口袋，effective 是「现在真正生效的」那几张，inheritable 是「exec 后愿意传给子进程」的候选。内核的特权检查只看 effective。</span></p><p><span class="marginnote">文件能力：给二进制标 cap，不必 suid root。容器常 drop 再加回少数位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在特权检查处查 <code>capable()</code>。对照 LSM：cap 是粗粒度特权，LSM 是强制访问。对照 [seccomp]：seccomp 滤系统调用，cap 滤特权操作。对照 <a href="/cs/dm-crypt">dm-crypt</a>：解锁盘可能要 cap 或 uid。</p>',9)),(i(),s(c,null,{default:e(()=>[r(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22uid%200%20%E5%85%A8%E8%83%BD%22%5D%20--%3E%20CAP%5B%22%E4%BD%8D%E5%9B%BE%E7%89%B9%E6%9D%83%22%5D%0A%20%20EXEC%5B%22execve%22%5D%20--%3E%20CALC%5B%22%E8%AE%A1%E7%AE%97%E6%96%B0%20cap%20%E9%9B%86%22%5D%0A%20%20CHK%5B%22%E7%89%B9%E6%9D%83%E6%93%8D%E4%BD%9C%22%5D%20--%3E%20EFF%5B%22effective%20%E4%BD%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>capabilities 缩小攻击面：被攻破的守护不必带完整 root。残留的 <code>SYS_ADMIN</code> 说明拆分不彻底。不要写成云 IAM。与 <a href="/cs/userfaultfd">userfaultfd</a>：操作别人地址空间另要 ptrace 等，不单是 cap。</p><p><span class="marginnote">数字实例：Web 服务想绑 80 端口，传统做法是 suid root，一旦被攻破就是全机沦陷；改用文件能力只授 <code>CAP_NET_BIND_SERVICE</code> 一位，即使被打穿，攻击者也写不了他人文件、加载不了模块。</span></p><p>调试：<code>getpcaps</code>、<code>/proc/self/status</code> 的 Cap 行。</p><p>实现上：bounding set 限制能获得的 cap，容器常用它做不可再加。ambient 让非 root 执行文件后仍留住某些 cap。CAP_SYS_ADMIN 几乎等于旧 root，拆分失败就在这里。 读法上只引用<a href="/cs/timer-wheel">上一课</a>的结论，不把对象换成训练推理或限价簿。</p>',5)),(i(),s(c,null,{default:e(()=>[r(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOX%5B%22%E5%AE%B9%E5%99%A8%E5%90%AF%E5%8A%A8%EF%BC%9Abounding%20set%20%E5%8F%AA%E7%95%99%E5%87%A0%E4%BD%8D%22%5D%20--%3E%20GRANT%5B%22%E8%BF%9B%E7%A8%8B%E8%A6%81%E7%BB%91%2080%20%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20GRANT%20--%3E%20OK%5B%22CAP_NET_BIND_SERVICE%20%E5%9C%A8%E5%A4%A9%E8%8A%B1%E4%B9%8B%E5%86%85%EF%BC%9A%E6%8E%88%E4%BA%88%E5%B9%B6%E7%94%9F%E6%95%88%22%5D%0A%20%20BOX%20--%3E%20DENY%5B%22%E8%BF%9B%E7%A8%8B%E5%90%8E%E6%9D%A5%E6%83%B3%E8%A6%81%20CAP_SYS_ADMIN%22%5D%0A%20%20DENY%20--%3E%20NO%5B%22%E8%B6%85%E5%87%BA%20bounding%20set%EF%BC%9A%E6%B0%B8%E8%BF%9C%E6%8B%BF%E4%B8%8D%E5%9B%9E%E6%9D%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：以为能力「先 drop 掉、需要时再加回」很灵活。实际上 bounding set 是不可超越的天花板，被 drop 出去的位在进程整个生命周期内都拿不回来——容器正是靠这一点实现「不可再加」。</span></p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>Linux capabilities</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入命名空间里 cap 的全部映射。不保证 Android 的额外位。下一课强制访问：LSM 与 SELinux。</p><p>版本字段会变，课序钉的是机制对象「Linux capabilities」，不是某一主线内核的结构体名。 后课默认：特权是位，不是单一 root。LSM 钩子与 SELinux 标签，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>capabilities 把 root 拆成可丢弃的位。</li><li>exec 与文件 cap 决定子进程特权。</li><li>LSM/SELinux 是下一课。</li><li>出处：Linux <code>capabilities(7)</code>；POSIX 草案；内核 security。</li></ul>',8))])}const h=n(d,[["render",A]]);export{f as __pageData,h as default};
